let rects = [];
let colors = ['#f71735', '#093e80', '#ecc30b', '#ffffff', '#2abde4'];

let gridW;
let gridH;
let rows = 7;
let cols = 7;

function setup() {
	createCanvas(900, 900);
	gridW = width * 0.9;
	gridH = height * 0.9;
	let cellW = gridW / cols;
	let cellH = gridH / rows;
	let sep = 4;
	for (let i = 0; i < cols; i++) {
		for (let j = 0; j < rows; j++) {
			let x = i * cellW + cellW / 2;
			let y = j * cellH + cellH / 2;
			let rectSize = cellW * 0.6;
			shuffle(colors, true);
			rects.push(new SuperRect(x - (rectSize / 2), y - (rectSize / 2), rectSize, rectSize, 0, sep, colors[1]));
			rects.push(new SuperRect(x + (rectSize / 2), y - (rectSize / 2), rectSize, rectSize, PI * 0.5, sep, colors[2]));
			rects.push(new SuperRect(x + (rectSize / 2), y + (rectSize / 2), rectSize, rectSize, PI, sep, colors[3]));
			rects.push(new SuperRect(x - (rectSize / 2), y + (rectSize / 2), rectSize, rectSize, PI * 1.5, sep, colors[4]));
		}
	}

	shuffle(rects, true);
}

function draw() {
	translate((width - gridW) / 2, (height - gridH) / 2);

	background('#000000');
	noStroke();
	for (let i = 0; i < rects.length; i++) {
		let r = rects[i];
		push();
		translate(r.x, r.y);
		rotate(r.a);
		fill(r.clr);
		rect(0, 0, r.w, r.h);
		pop();
	}

	strokeWeight(width * 0.006);
	stroke('#000000');
	for (let i = 0; i < rects.length; i++) {
		let r = rects[i];
		push();
		translate(r.x, r.y);
		rotate(r.a);
		noFill();
		rect(0, 0, r.w, r.h);
		pop();
	}

	for (let i of rects) {
		i.move();
	}
}

function easeInOutQuint(x) {
	return x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2;
}

class SuperRect {
	constructor(x, y, w, h, a, sep, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.a = a;
		this.clr = clr;
		this.separate = sep;
		this.originW = w;
		this.originH = h;
		this.setValues();
		this.w = this.toW;
		this.h = this.toH;
		this.setValues();
		this.toggle = false;
		this.duration = 90;
	}

	move() {
		if (this.toggle) {
			this.time++;
			if (0 < this.time && this.time < this.duration) {
				let n = norm(this.time, 0, this.duration);
				this.w = lerp(this.fromW, this.toW, easeInOutQuint(n));
				this.h = lerp(this.fromH, this.toH, easeInOutQuint(n));
			} else if (this.duration < this.time) {
				this.toggle = false
			}
		}
		if ((this.toggle == false) && (frameCount % 30 == 0) && (random() < 0.1)) {
			this.toggle = true;
			this.time = 0;
			this.setValues();
		}
	}

	setValues() {
		this.fromW = this.w;
		this.toW = (this.originW / this.separate) * int(random(this.separate) + 1);
		this.fromH = this.h;
		this.toH = (this.originH / this.separate) * int(random(this.separate) + 1);
		this.time = 0;
	}
}

